<template><div class="page-container"><div class="page-header"><div><h2>固定资产管理与申领</h2><p>资产台账、购置领用申请与部门审批</p></div><div><el-input-number v-model="deptId" :min="1" placeholder="部门ID"/><el-button @click="load">筛选部门</el-button><el-button type="primary" @click="openApply">发起申请</el-button></div></div>
<el-card shadow="never"><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="assetName" label="资产名称"/><el-table-column prop="assetType" label="类型"/><el-table-column prop="quantity" label="数量"/><el-table-column prop="deptId" label="部门ID"/><el-table-column prop="applyUserId" label="申请人"/><el-table-column label="资产状态"><template #default="s">{{ ['','在库','已领用','报废'][s.row.status] }}</template></el-table-column><el-table-column label="审批"><template #default="s"><el-tag :type="['warning','success','danger'][s.row.approveStatus]">{{ ['待审批','已通过','已拒绝'][s.row.approveStatus] }}</el-tag></template></el-table-column><el-table-column label="操作" width="170"><template #default="s"><template v-if="s.row.approveStatus===0"><el-button type="success" link @click="approve(s.row,1)">通过</el-button><el-button type="danger" link @click="approve(s.row,0)">拒绝</el-button></template><el-button type="danger" link @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></el-card>
<el-dialog v-model="visible" title="资产购置/领用申请" width="500"><el-form label-width="90"><el-form-item label="资产名称"><el-input v-model="form.assetName"/></el-form-item><el-form-item label="类型"><el-select v-model="form.assetType"><el-option v-for="v in ['设备','办公用品','其他']" :key="v" :value="v"/></el-select></el-form-item><el-form-item label="数量"><el-input-number v-model="form.quantity" :min="1"/></el-form-item><el-form-item label="部门ID"><el-input-number v-model="form.deptId" :min="1"/></el-form-item><el-form-item label="申请人ID"><el-input-number v-model="form.applyUserId" :min="1"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="submit">提交申请</el-button></template></el-dialog></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{assetAPI}from'@/api/getData.js';const deptId=ref(),rows=ref([]),loading=ref(false),visible=ref(false),form=reactive({assetName:'',assetType:'设备',quantity:1,deptId:1,applyUserId:1});const load=async()=>{loading.value=true;try{const r=await assetAPI.list(deptId.value);if(r&&r!==-1)rows.value=r.data||[]}finally{loading.value=false}};const openApply=()=>visible.value=true;const submit=async()=>{const r=await assetAPI.apply({...form});if(r&&r!==-1){ElMessage.success('申请已提交');visible.value=false;load()}};const approve=async(row,v)=>{const r=await assetAPI.approve(row.assetId,v);if(r&&r!==-1){ElMessage.success('审批完成');load()}};const remove=async row=>{await ElMessageBox.confirm('确认删除该资产记录？','提示');const r=await assetAPI.remove(row.assetId);if(r&&r!==-1)load()};onMounted(load);</script>
<style scoped>.page-container{padding:24px;background:#f5f7fa;min-height:100vh}.page-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.page-header h2{margin:0}.page-header p{color:#909399}.page-header>div:last-child{display:flex;gap:10px}</style>
